-- Carga real del SGA (sistema externo) — carreras, materias, personas, cuentas de acceso
-- provisorias y asignaciones docente-materia.
--
-- Los `azure_oid` de `identity.users` son PROVISORIOS (aleatorios): `VinculadorPrimerLogin`
-- los reemplaza por el oid real la primera vez que cada persona hace login con Azure AD,
-- localizándola por `upn` y preservando el mismo `users.id` (y por lo tanto sus
-- `user_roles` ya cargados). Ver backend/src/ArsDocendi.Shared/Identity/VinculadorPrimerLogin.cs.
--
-- 58 materias no estaban en el export de plan de estudios vigente
-- (pertenecen a planes activos pero no vigentes) y se crearon acá con el nombre que trae
-- materias_docente.csv, para no perder esas asignaciones.
--
-- Excluye 80 asociaciones docente-materia de 30 docentes cuyo documento no aparece en el
-- padrón de docentes, y 2 personas sin un mail institucional único utilizable (comparten el
-- placeholder "sincorreo@unlam.edu.ar"). Esas quedan sin `user_roles` hasta resolverse.

BEGIN;

-- Carreras
ON CONFLICT (id) DO UPDATE SET code = EXCLUDED.code, name = EXCLUDED.name, is_active = EXCLUDED.is_active;

-- Materias (una fila por combinación materia+carrera)
ON CONFLICT (id) DO UPDATE SET
    code = EXCLUDED.code, name = EXCLUDED.name, carrera_id = EXCLUDED.carrera_id, is_active = EXCLUDED.is_active;

-- Personas
ON CONFLICT (id) DO UPDATE SET
    cuil = EXCLUDED.cuil, legajo = EXCLUDED.legajo, nombre = EXCLUDED.nombre, apellido = EXCLUDED.apellido,
    fecha_nacimiento = EXCLUDED.fecha_nacimiento, telefono = EXCLUDED.telefono;

-- Cuentas (oid provisorio; se reconcilia solo en el primer login real)
ON CONFLICT (id) DO UPDATE SET display_name = EXCLUDED.display_name, persona_id = EXCLUDED.persona_id;

-- Rol Docente por materia
ON CONFLICT (user_id, role_id, materia_id, carrera_id) WHERE deleted_at IS NULL DO NOTHING;

COMMIT;
